#!/usr/bin/env python3
from itertools import permutations

def analyze_string(s):
    print(f"Original string: {s}")
    print(f"Length: {len(s)}")
    print(f"Unique chars: {set(s)}")
    print(f"Positions of key chars:")
    for c in ['f', 'l', 'a', 'g', '{', '}']:
        if c in s:
            print(f"'{c}' at position {s.index(c)}")
    print()

def reverse_string(s):
    return s[::-1]

def split_and_check(s):
    valid_flags = set()
    # Try splitting into different segments
    for i in range(1, len(s)-1):
        for j in range(i+1, len(s)):
            # Split into 3 parts and try combinations
            p1 = s[:i]
            p2 = s[i:j]
            p3 = s[j:]

            # Try different arrangements of the parts
            arrangements = [p1+p2+p3, p1+p3+p2, p2+p1+p3, p2+p3+p1, p3+p1+p2, p3+p2+p1]

            for arr in arrangements:
                if arr.startswith("flag{") and arr.endswith("}"):
                    valid_flags.add(arr)
    return valid_flags

def find_valid_flags(orig_str):
    valid_flags = set()
    # Get all characters from string
    chars = list(orig_str)

    # Generate permutations but limit to first 1000000 to avoid memory issues
    count = 0
    for p in permutations(chars):
        flag = ''.join(p)
        if flag.startswith("flag{") and flag.endswith("}"):
            valid_flags.add(flag)
        count += 1
        if count >= 1000000:
            break
    return valid_flags

def main():
    orig_str = "_m3lur3nudfl}_an4ggw{"

    print("String Analysis:")
    analyze_string(orig_str)

    print("Reversed string:")
    rev = reverse_string(orig_str)
    print(rev)
    if rev.startswith("flag{") and rev.endswith("}"):
        print("Reversed string is valid flag format!")
    print()

    # Find patterns by analyzing segments
    print("Looking for patterns in 2-char segments:")
    for i in range(0, len(orig_str)-1, 2):
        print(orig_str[i:i+2], end=' ')
    print("\n")

    print("Looking for patterns in 3-char segments:")
    for i in range(0, len(orig_str)-2, 3):
        print(orig_str[i:i+3], end=' ')
    print("\n")

    print("Looking for valid flag arrangements...")
    # Try split and check method
    valid_from_split = split_and_check(orig_str)
    if valid_from_split:
        print("Found valid flags from splitting:")
        for flag in valid_from_split:
            print(flag)

    # Try permutations method
    valid_from_perm = find_valid_flags(orig_str)
    if valid_from_perm:
        print("\nFound valid flags from permutations:")
        for flag in valid_from_perm:
            print(flag)

if __name__ == "__main__":
    main()

