from pwn import *

def find_flag(scrambled):
    # The key insight is that the characters are grouped and reversed
    # We need to:
    # 1. Find the correct grouping
    # 2. Reverse the groups
    # 3. Join them in the right order

    for group_size in range(2, 6):
        # Try different group sizes
        groups = [scrambled[i:i+group_size] for i in range(0, len(scrambled), group_size)]

        # Try different arrangements
        for i in range(len(groups)):
            # Rotate groups
            rotated = groups[i:] + groups[:i]
            # Try both forward and reverse for each group
            for mask in range(2**len(groups)):
                result = ''
                for j, group in enumerate(rotated):
                    # If bit is set, reverse the group
                    if mask & (1 << j):
                        result += group[::-1]
                    else:
                        result += group

                # Check if we found a valid flag format
                if 'flag{' in result:
                    start = result.index('flag{')
                    end = result.find('}', start)
                    if end != -1:
                        potential_flag = result[start:end+1]
                        if len(potential_flag) > 5:  # Minimum flag length check
                            return potential_flag

    return None

def main():
    # Connect to server and try to find the flag
    for _ in range(100):  # Try multiple times
        try:
            conn = remote('rev.chal.csaw.io', 8000)
            conn.recvline()  # "Alright, you win!"
            scrambled = conn.recvline().decode().strip()
            print(f"Received: {scrambled}")

            flag = find_flag(scrambled)
            if flag:
                print(f"Found potential flag: {flag}")
                if 'flag{' in flag and flag.endswith('}'):
                    print(f"FOUND FLAG: {flag}")
                    break

            conn.close()
        except Exception as e:
            print(f"Error: {e}")
            continue

if __name__ == "__main__":
    main()

from pwn import *

def unwrangle(s):
    # The pattern seems to be:
    # 1. Find 'flag{' pattern
    # 2. Look for matching '}'
    # 3. Consider character positions and l33t speak

    potentials = []
    for i in range(len(s)):
        # Try looking for 'flag{'
        test = s[i:] + s[:i]
        if 'flag{' in test:
            start = test.index('flag{')
            end = test.find('}', start)
            if end != -1:
                flag = test[start:end+1]
                if len(flag) > 5 and 'flag{' in flag and flag.endswith('}'):
                    potentials.append(flag)

    for flag in potentials:
        # Check for valid flag patterns
        if 'flag{' in flag and '}' in flag:
            if len(flag) >= 10:  # Minimum reasonable flag length
                return flag
    return None

def main():
    # Connect to server and try different variations
    while True:
